import{c as t,Q as a,j as n,m as s}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"From Model Scaling to System Scaling: Scaling the Harness in Agentic AI","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.26112","title":"From Model Scaling to System Scaling: Scaling the Harness in Agentic AI","archived_date":"2026-07-09T00:00:00.000Z","arxiv_id":2605.26112,"authors":["Shangding Gu"],"domains":["cs.AI","cs.LG"],"license":"arXiv non-exclusive","pdf_path":"pdfs/2605.26112.pdf","published_date":"2026-05-25T00:00:00.000Z","tags":["harness-scaling","system-scaling","dynamic-skill-routing","context-governance","trustworthy-memory","agent-harness","cheetahclaws"]},"headers":[],"relativePath":"research/papers/2026-05-25-scaling-harness-system-scaling-agentic-ai-2605-26112.md","filePath":"research/papers/2026-05-25-scaling-harness-system-scaling-agentic-ai-2605-26112.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-05-25-scaling-harness-system-scaling-agentic-ai-2605-26112.md"};function i(r,e,l,c,d,m){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="from-model-scaling-to-system-scaling-scaling-the-harness-in-agentic-ai" tabindex="-1">From Model Scaling to System Scaling: Scaling the Harness in Agentic AI <a class="header-anchor" href="#from-model-scaling-to-system-scaling-scaling-the-harness-in-agentic-ai" aria-label="Permalink to &quot;From Model Scaling to System Scaling: Scaling the Harness in Agentic AI&quot;">​</a></h1><p><strong>arXiv</strong>: <a href="https://arxiv.org/abs/2605.26112" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.26112</a><br><strong>Code</strong>: <a href="https://github.com/SafeRL-Lab/cheetahclaws" target="_blank" rel="noreferrer">https://github.com/SafeRL-Lab/cheetahclaws</a><br><strong>PDF</strong>: pdfs/2605.26112.pdf</p><hr><h2 id="中文說明-workspace-意涵" tabindex="-1">中文說明（workspace 意涵） <a class="header-anchor" href="#中文說明-workspace-意涵" aria-label="Permalink to &quot;中文說明（workspace 意涵）&quot;">​</a></h2><p>本論文提出「system scaling」概念: agentic AI 的下一個瓶頸不是模型規模,而是 harness（結構化執行層）的設計品質。作者定義 agent harness = 基礎模型 + 記憶基質 + context 建構器 + skill-routing 層 + 編排迴圈 + 驗證治理層的組合體,並提出三個核心瓶頸: context governance、trustworthy memory、dynamic skill routing。</p><p><strong>對 Fusion 架構的直接意義</strong>: 論文 §4.3 &quot;Dynamic Skill Routing and Verification&quot; 正是 Devin Fusion sidekick 路由和 workspace multi-mode-skill 路由的學術框架化。作者主張「skill routing across tools and subagents」是 harness-level 的 first-class 設計對象,非模型層的附屬品。這為本 workspace 的 Fusion 架構提供了學術 ground truth: 路由策略不是「選模型」的優化,而是「scaling the harness」的系統級設計。</p><p><strong>與 workspace 既有研究的對齊</strong>: 論文的「harness-level benchmarks」議程（trajectory quality、memory hygiene、context efficiency、verification cost）與 workspace DeepSWE 實證（harness quality = 評測第一獨立變數,同模型跨 harness 差 23.8pt）完全一致。CheetahClaws 參考實現與 Claude Code 的對比分析,可作為 workspace 跨 harness 可攜性（Omnigent）研究的補充參考。</p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>This paper studies the next major bottleneck in agentic AI as <em>system scaling</em>, not only model scaling: the design of auditable, persistent, modular, and verifiable architectures around foundation models. We refer to this shift as <em>scaling the harness</em>: treating the structured execution layer around a foundation model as a first-class object of design, evaluation, and optimization. Recent progress in large language models (LLMs) has enabled agents that use tools, retrieve information, maintain memory, and execute long-horizon workflows. Yet evaluation remains largely model-centric, reducing agents to final-task success or benchmark accuracy while treating memory, retrieval, tool use, orchestration, verification, and governance as secondary implementation details. This framing is increasingly inadequate: agent performance emerges from the interaction among the foundation model, memory substrate, context constructor, skill-routing layer for tools and subagents, orchestration loop, and verification-and-governance layer. Together, these components form the agent harness, the system that translates model capability into long-horizon agent behavior. We therefore study <em>scaling the harness</em> through three core bottlenecks in agentic AI: <em>context governance</em>, <em>trustworthy memory</em>, and <em>dynamic skill routing</em>, together with the orchestration and governance mechanisms that coordinate and constrain them. We further outline a research agenda for harness-level benchmarks that operationalize system scaling, going beyond one-shot task success to measure trajectory quality, memory hygiene, context efficiency, communication fidelity, verification cost, and safe evolution over time. Alongside the framework, we develop and release <code>CheetahClaws</code>, a Python-native reference harness, and use it together with Claude Code and OpenClaw as concrete points of comparison that make harness-level design choices explicit. Our main claim is that future progress in agentic AI will depend as much on system design as on stronger foundation models.</p><h2 id="_1-introduction" tabindex="-1">1 Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1 Introduction&quot;">​</a></h2><p>The dominant story of recent AI progress has been <em>model scaling</em>: larger models, more data, stronger post-training, and higher benchmark scores. For agentic AI, this story is now incomplete. Once foundation models are embedded into tools, terminals, browsers, repositories, memory stores, and external services, their behavior is no longer determined by the model alone. It is determined by a <em>system</em>: how context is constructed, how memory is retrieved, how tools are invoked, how subagents are routed, how actions are verified, and how failures are audited.</p><p>Our key claim is therefore that <strong>agentic AI should be studied and evaluated as a system-scaling problem, not merely as a model-scaling problem.</strong> By <em>model scaling</em>, we refer to improvements in the standalone foundation model. By <em>system scaling</em>, we refer to improvements in the surrounding architecture, including memory, context construction, skill routing across tools and subagents, orchestration, and verification-and-governance, and how these components adapt over time.</p><p>Modern agentic systems already illustrate what scaling the harness looks like in practice. Production harnesses such as Claude Code and OpenClaw couple foundation models to tools, subagents, and persistent project memory. Research-side harnesses such as SWE-agent further show that careful tool-schema design alone can improve benchmark accuracy substantially even with a fixed backbone model.</p><p>This perspective is highlighted by recent empirical findings: what is often reported as a model score is in fact a <strong>model-plus-harness score</strong>. Context length does not guarantee effective information access because attention dilutes over long inputs. Multi-agent systems can outperform single agents on breadth-first tasks but introduce coordination failures that single-agent metrics miss.</p><h3 id="three-main-contributions" tabindex="-1">Three Main Contributions <a class="header-anchor" href="#three-main-contributions" aria-label="Permalink to &quot;Three Main Contributions&quot;">​</a></h3><ol><li><strong>System-scaling framing.</strong> Progress depends on <em>scaling the harness</em>, not only scaling the model.</li><li><strong>Harness-level framework.</strong> Separates base-model reasoning from system factors including memory, context construction, skill routing, orchestration, and verification-and-governance.</li><li><strong>Evaluation agenda and reference harness.</strong> Future benchmarks should measure process-level and longitudinal properties such as trajectory quality, memory hygiene, context efficiency, verification cost, safe evolution, and robustness under repeated use. <code>CheetahClaws</code> is developed as a Python-native reference harness, compared against Claude Code and OpenClaw.</li></ol><h2 id="_3-system-scaling-a-framework-for-agentic-ai" tabindex="-1">3 System Scaling: A Framework for Agentic AI <a class="header-anchor" href="#_3-system-scaling-a-framework-for-agentic-ai" aria-label="Permalink to &quot;3 System Scaling: A Framework for Agentic AI&quot;">​</a></h2><h3 id="_3-1-agent-harnesses-as-system-infrastructure" tabindex="-1">3.1 Agent Harnesses as System Infrastructure <a class="header-anchor" href="#_3-1-agent-harnesses-as-system-infrastructure" aria-label="Permalink to &quot;3.1 Agent Harnesses as System Infrastructure&quot;">​</a></h3><p>The agent harness is the structured execution layer that translates model capability into long-horizon agent behavior. It comprises six core components:</p><ol><li><strong>Foundation model</strong>: The base LLM providing reasoning and generation</li><li><strong>Memory substrate</strong>: Persistent storage for facts, decisions, and trajectories</li><li><strong>Context constructor</strong>: Assembles prompts from memory, tools, and current state</li><li><strong>Skill-routing layer</strong>: Routes tasks to appropriate tools, subagents, or models</li><li><strong>Orchestration loop</strong>: Manages the agent&#39;s think-act-observe cycle</li><li><strong>Verification-and-governance layer</strong>: Validates outputs and enforces safety constraints</li></ol><h3 id="_3-2-prompt-skill-and-memory-as-temporal-layers" tabindex="-1">3.2 Prompt, Skill, and Memory as Temporal Layers <a class="header-anchor" href="#_3-2-prompt-skill-and-memory-as-temporal-layers" aria-label="Permalink to &quot;3.2 Prompt, Skill, and Memory as Temporal Layers&quot;">​</a></h3><p>The harness manages three temporal layers of information:</p><ul><li><strong>Prompt</strong> (immediate): Current user request and system instructions</li><li><strong>Skill</strong> (medium-term): Reusable procedures and tool-use patterns</li><li><strong>Memory</strong> (long-term): Persistent knowledge accumulated across sessions</li></ul><h2 id="_4-three-bottlenecks-in-system-scaling" tabindex="-1">4 Three Bottlenecks in System Scaling <a class="header-anchor" href="#_4-three-bottlenecks-in-system-scaling" aria-label="Permalink to &quot;4 Three Bottlenecks in System Scaling&quot;">​</a></h2><h3 id="_4-1-context-governance" tabindex="-1">4.1 Context Governance <a class="header-anchor" href="#_4-1-context-governance" aria-label="Permalink to &quot;4.1 Context Governance&quot;">​</a></h3><p>Context governance addresses what should be retrieved, compressed, ordered, refreshed, trusted, and kept active at each step. Key challenges include:</p><ul><li>Attention dilution over long inputs (lost-in-the-middle effect)</li><li>Context window management vs. effective information access</li><li>Dynamic context construction based on task demands</li></ul><h3 id="_4-2-trustworthy-memory" tabindex="-1">4.2 Trustworthy Memory <a class="header-anchor" href="#_4-2-trustworthy-memory" aria-label="Permalink to &quot;4.2 Trustworthy Memory&quot;">​</a></h3><p>Memory quality involves:</p><ul><li>What to store and what to discard</li><li>How to retrieve the right information at the right time</li><li>Avoiding staleness, drift, contamination, and over-generalization</li><li>Memory as a first-class data management system, not just a storage layer</li></ul><h3 id="_4-3-dynamic-skill-routing-and-verification" tabindex="-1">4.3 Dynamic Skill Routing and Verification <a class="header-anchor" href="#_4-3-dynamic-skill-routing-and-verification" aria-label="Permalink to &quot;4.3 Dynamic Skill Routing and Verification&quot;">​</a></h3><p><strong>中文說明</strong>: 本節是 Fusion 架構的學術對應。Skill routing 不只是「選哪個模型」,而是跨工具、跨 subagent、跨模型的動態分配,且需驗證路由決策本身是否正確。</p><p>Dynamic skill routing determines how tasks are dispatched across tools, subagents, and potentially different models. Key challenges:</p><ul><li>Routing decisions must consider task complexity, model capability, and cost</li><li>Verification of routing decisions: was the right agent/model selected?</li><li>Fallback mechanisms when initial routing proves inadequate</li><li>Cost-quality tradeoffs in routing decisions</li></ul><p>This directly corresponds to the &quot;sidekick&quot; pattern in production systems (e.g., Devin Fusion), where a frontier model delegates mechanical work to a cost-effective model while maintaining planning and review ownership.</p><h2 id="_5-toward-system-level-evaluation-and-agent-evolution" tabindex="-1">5 Toward System-Level Evaluation and Agent Evolution <a class="header-anchor" href="#_5-toward-system-level-evaluation-and-agent-evolution" aria-label="Permalink to &quot;5 Toward System-Level Evaluation and Agent Evolution&quot;">​</a></h2><h3 id="_5-1-from-outcome-metrics-to-process-metrics" tabindex="-1">5.1 From Outcome Metrics to Process Metrics <a class="header-anchor" href="#_5-1-from-outcome-metrics-to-process-metrics" aria-label="Permalink to &quot;5.1 From Outcome Metrics to Process Metrics&quot;">​</a></h3><p>Future benchmarks should measure:</p><ul><li><strong>Trajectory quality</strong>: Are the intermediate steps efficient and correct?</li><li><strong>Memory hygiene</strong>: Is memory accurate, non-redundant, and non-stale?</li><li><strong>Context efficiency</strong>: Is the context window used effectively?</li><li><strong>Communication fidelity</strong>: In multi-agent systems, is information accurately transmitted?</li><li><strong>Verification cost</strong>: How much overhead does verification add?</li></ul><h3 id="_5-2-from-single-episodes-to-longitudinal-evaluation" tabindex="-1">5.2 From Single Episodes to Longitudinal Evaluation <a class="header-anchor" href="#_5-2-from-single-episodes-to-longitudinal-evaluation" aria-label="Permalink to &quot;5.2 From Single Episodes to Longitudinal Evaluation&quot;">​</a></h3><p>Pass^k evaluation (probability of succeeding on k independent rollouts) exposes reliability gaps that single-shot accuracy hides. Longitudinal evaluation tracks:</p><ul><li>Skill drift over time</li><li>Memory staleness</li><li>Adaptation quality</li></ul><h3 id="_5-3-standards-for-safe-agent-evolution" tabindex="-1">5.3 Standards for Safe Agent Evolution <a class="header-anchor" href="#_5-3-standards-for-safe-agent-evolution" aria-label="Permalink to &quot;5.3 Standards for Safe Agent Evolution&quot;">​</a></h3><p>Agent evolution requires standards for:</p><ul><li>How agents update skills</li><li>How agents refine memory</li><li>How agents communicate across roles</li><li>How agents remain auditable as they adapt</li></ul><h2 id="_6-discussion-alternative-views-and-limitations" tabindex="-1">6 Discussion: Alternative Views and Limitations <a class="header-anchor" href="#_6-discussion-alternative-views-and-limitations" aria-label="Permalink to &quot;6 Discussion: Alternative Views and Limitations&quot;">​</a></h2><p>The system-scaling framing does not claim model scaling no longer matters. Rather, once models reach a sufficient capability threshold, many additional gains in long-horizon agent performance increasingly depend on system design. The framework is also limited by the immaturity of harness-level benchmarks — most existing benchmarks remain model-centric.</p><h2 id="_7-conclusion" tabindex="-1">7 Conclusion <a class="header-anchor" href="#_7-conclusion" aria-label="Permalink to &quot;7 Conclusion&quot;">​</a></h2><p>Future progress in agentic AI will depend as much on system design as on stronger foundation models. The agent harness — encompassing memory, context, skill routing, orchestration, and verification — should be treated as a first-class object of design, evaluation, and optimization. The release of <code>CheetahClaws</code> provides a concrete reference point for harness-level design choices, and the proposed evaluation agenda offers a path toward benchmarks that measure what actually matters for long-horizon agent performance.</p><hr><blockquote><p><strong>PDF</strong>: <code>pdfs/2605.26112.pdf</code> (419 KB, 11 pages)<br><strong>Figures</strong>: <code>pdfs/figures/2605.26112/</code> (9 PNG images)<br><strong>Code</strong>: <a href="https://github.com/SafeRL-Lab/cheetahclaws" target="_blank" rel="noreferrer">https://github.com/SafeRL-Lab/cheetahclaws</a></p></blockquote>',52)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
